import React from 'react';
import Header from '../components/Header';
import DeckSelector from '../components/DeckSelector';
import UpgradeView from '../components/UpgradeView';
import CTAButton from '../components/CTAButton';
import { Deck, BudgetLevel } from '../lib/types';
// Importamos el JSON directamente, evitando el uso de 'fs' y 'path'
import db from '../data/data.json';

// Next.js pasa automáticamente los parámetros de la URL (searchParams) a la página principal
interface PageProps {
  searchParams: {
    deck?: string;
    budget?: string;
  };
}

export default async function Home({ searchParams }: PageProps) {
  // Obtenemos los mazos directamente del JSON importado y lo tipamos
  const decks: Deck[] = db.decks as Deck[];

  // Mapeamos los mazos al formato que espera nuestro selector
  const minimalDecks = decks.map(d => ({
    id: d.id,
    name: d.name,
    commander: d.commander
  }));

  // Extraemos los parámetros de la URL o usamos valores por defecto
  const currentDeckId = searchParams.deck || decks[0]?.id;
  const currentBudget = (searchParams.budget as BudgetLevel) || 'budget';

  // Buscamos el mazo seleccionado y extraemos sus cartas según el presupuesto
  const selectedDeck = decks.find(d => d.id === currentDeckId) || decks[0];
  const selectedUpgrades = selectedDeck.upgrades[currentBudget] || { add: [], remove: [] };

  return (
    <>
      <Header />
      <main className="flex flex-col items-center justify-start p-4 md:p-8 lg:p-12 max-w-7xl mx-auto w-full">
        
        {/* Cabecera de texto de la página */}
        <div className="text-center mb-10 mt-6">
          <h2 className="text-3xl md:text-5xl font-extrabold text-white mb-4 tracking-tight">
            Mejora tu Mazo Preconstruido
          </h2>
          <p className="text-gray-400 text-base md:text-lg max-w-2xl mx-auto">
            Selecciona tu mazo y presupuesto. Te mostramos exactamente qué cartas debes sacar (rojo) y cuáles debes añadir (verde) para maximizar tu poder en la mesa.
          </p>
        </div>

        {/* Componente interactivo de selección */}
        <DeckSelector decks={minimalDecks} />
        
        {/* Previsualización del mazo seleccionado */}
        {selectedDeck && (
          <div className="w-full mt-2 flex flex-col md:flex-row items-center justify-center gap-4 mb-8 bg-surface/30 py-4 rounded-2xl border border-surfaceHover">
            <img 
              src={selectedDeck.image} 
              alt={selectedDeck.name} 
              className="w-20 md:w-24 h-auto rounded-lg shadow-lg border-2 border-surfaceHover" 
            />
            <div className="text-center md:text-left">
              <h3 className="text-xl md:text-2xl font-bold text-white">{selectedDeck.name}</h3>
              <p className="text-primary text-sm font-semibold mt-1">Comandante: {selectedDeck.commander}</p>
            </div>
          </div>
        )}

        {/* Listado de cartas visual (rojo/verde) */}
        <UpgradeView tier={selectedUpgrades} />
        
        {/* Call to Action Final */}
        <CTAButton 
          text="Comprar cartas en Cardmarket" 
          href="https://www.cardmarket.com/" 
        />
      </main>
    </>
  );
}